const body = $json.body ?? {};
return [{ json: {
  company: 'Thái Duy Digital',
  transactionDate: new Date().toISOString().slice(0, 10),
  deliveryDate: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10),
  customerName: body.customerName,
  salesOrder: body.salesOrder,
  itemCode: body.itemCode,
  fakeSalesOrderName: body.fakeSalesOrderName ?? 'BAD / DOC NAME With Space'
} }];

const failures = [
  ['duplicateItem', $node['Duplicate Item Create Should Fail'].json],
  ['salesOrderMissingCustomer', $node['Sales Order Missing Customer Should Fail'].json],
  ['deleteSubmittedSalesOrder', $node['Delete Submitted Sales Order Should Fail'].json],
  ['getFakeSalesOrder', $node['Get Fake Sales Order Should Fail'].json],
];
const failedAsExpected = failures.map(([name, value]) => ({ name, hasError: Boolean(value.error), message: value.error ?? null }));
const serialized = JSON.stringify(failedAsExpected);
const patterns = [/api[_-]?key/i, /api[_-]?secret/i, /authorization/i, /token\s+[A-Za-z0-9]/i, /password/i];
const securityFindings = patterns.filter((pattern) => pattern.test(serialized)).map((pattern) => pattern.toString());
return [{ json: {
  status: failedAsExpected.every((item) => item.hasError) && securityFindings.length === 0 ? 'passed' : 'needs_review',
  salesOrderUnderTest: $node['Build Negative Context'].json.salesOrder,
  failedAsExpected,
  securityFindings,
  responsePolicy: 'Only sanitized error messages and leak-scan status are returned.'
} }];
